const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
let ticking=false;addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(()=>{document.querySelector('.progress').style.width=(scrollY/(document.documentElement.scrollHeight-innerHeight)*100)+'%';if(!reduced){const section=document.querySelector('.landscape');const y=section.getBoundingClientRect().top;section.querySelector('img').style.transform=`translateY(${Math.max(-70,Math.min(70,y*.1))}px)`}ticking=false});ticking=true}},{passive:true});
const notes=[['I.','THE TOP NOTES','A little light. A new beginning.','Imagine the brightness of bergamot meeting the warm shimmer of saffron. The opening is an invitation: stop for a moment, and breathe.','#c69e51'],['II.','THE HEART NOTES','The moment you lean closer.','Soft rose and a whisper of jasmine. As the brightness settles, a softer, more intimate story begins to bloom.','#b97f72'],['III.','THE BASE NOTES','Some feelings never really leave.','Imagine amber, sandalwood and a veil of musk. A quiet, enveloping warmth — the memory that remains when the moment has passed.','#7e7954']];
const tabs=[...document.querySelectorAll('[data-note]')];function setNote(i){tabs.forEach((b,n)=>{b.setAttribute('aria-selected',n===i);b.tabIndex=n===i?0:-1});const n=notes[i];['noteNumber','noteType','noteTitle','noteDescription'].forEach((id,k)=>document.getElementById(id).textContent=n[k]);document.getElementById('noteOrb').style.background=`radial-gradient(circle at 30% 25%,#faf2de,${n[4]} 50%,#504933)`}tabs.forEach((b,i)=>{b.onclick=()=>setNote(i);b.onkeydown=e=>{if(['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();const next=(i+(e.key==='ArrowRight'?1:2))%3;setNote(next);tabs[next].focus()}}});setNote(0);
const products=[{name:'Amber Reverie',mood:'WARM · WOODY · ENVELOPING',description:'For the moments that glow long after sunset. An imagined composition of golden warmth, soft spice and a beautifully lingering woodiness.',top:'Bergamot · Saffron',heart:'Rose · Labdanum',base:'Amber · Sandalwood · Musk'},{name:'Rose Afterglow',mood:'FLORAL · SOFT · LUMINOUS',description:'A soft light, a half-remembered garden. A floral daydream where rose meets delicate petals and a gentle, embracing warmth.',top:'Pink pepper · Pear',heart:'Rose · Jasmine',base:'Musk · Soft woods'},{name:'Wild Stillness',mood:'FRESH · GREEN · GROUNDED',description:'An open window. A quiet forest. A green, spacious composition imagined for those who find their energy in moments of stillness.',top:'Bergamot · Green leaves',heart:'Tea · Iris',base:'Vetiver · Cedarwood'}];
const modal=document.getElementById('detail'),content=document.getElementById('dialogContent');let opener;function open(html){opener=document.activeElement;content.innerHTML=html;if(!modal.open)modal.showModal()}function product(i,match=false){const p=products[i];open(`<p class="eyebrow">${match?'YOUR SCENT EXPRESSION':'THE CONCEPT COLLECTION'}</p><h2>${p.name}</h2><p class="eyebrow">${p.mood}</p><p style="margin-top:20px">${p.description}</p><div class="scent-notes"><p><strong>TOP</strong>${p.top}</p><p><strong>HEART</strong>${p.heart}</p><p><strong>BASE</strong>${p.base}</p></div><p>Concept fragrance. Final compositions, sizes, pricing and availability will be announced by Shrinika Fragrances.</p><button class="round-cta" id="again">${match?'Explore again':'Find my scent'} ↗</button>`);document.getElementById('again').onclick=quiz}document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>product(+b.dataset.product));
let first=0;function quiz(){open('<p class="eyebrow">YOUR SCENT JOURNEY · 1 / 2</p><h2>Where would you<br><em>rather be?</em></h2><p>Choose the moment that draws you in.</p><div class="choices"><button data-choice="0">01 — In the warmth of a golden sunset ↗</button><button data-choice="1">02 — In a garden just after the rain ↗</button><button data-choice="2">03 — In the quiet of a green forest ↗</button></div>');content.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{first=+b.dataset.choice;stepTwo()})}function stepTwo(){open('<p class="eyebrow">YOUR SCENT JOURNEY · 2 / 2</p><h2>What stays<br><em>with you?</em></h2><p>Follow your instinct.</p><div class="choices"><button data-choice="0">The comfort of warmth and depth ↗</button><button data-choice="1">The softness of a beautiful moment ↗</button><button data-choice="2">The freedom of a fresh beginning ↗</button></div><button class="quiz-back">← Previous question</button>');content.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>product(first===+b.dataset.choice?first:+b.dataset.choice,true));content.querySelector('.quiz-back').onclick=quiz}document.querySelectorAll('[data-quiz]').forEach(b=>b.onclick=quiz);modal.querySelector('.close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});modal.addEventListener('close',()=>{if(opener?.isConnected)opener.focus()});document.getElementById('credits').onclick=()=>open('<p class="eyebrow">IMAGE CREDITS</p><h2>Inspired by nature.</h2><p>Landscape and floral stock photography served from Unsplash. Brand bottle visuals are custom concept artwork rendered in 3D and CSS.</p><div class="scent-notes"><p><a href="https://images.unsplash.com/photo-1509316785289-025f5b846b35" target="_blank" rel="noopener">Landscape photography ↗</a></p><p><a href="https://images.unsplash.com/photo-1490750967868-88aa4486c946" target="_blank" rel="noopener">Floral photography ↗</a></p></div>');document.getElementById('year').textContent=new Date().getFullYear();
